package com.quicknotes.app;

import android.app.*;
import android.os.*;
import android.content.*;
import android.net.Uri;
import android.provider.OpenableColumns;
import android.webkit.*;
import android.database.Cursor;
import org.json.*;
import java.io.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.zip.*;

public class MainActivity extends Activity {
    WebView web; final ExecutorService io=Executors.newSingleThreadExecutor();
    final Handler handler=new Handler(Looper.getMainLooper()); boolean destroyed=false;
    static final int ATTACH=1,CREATE_SYNC=2,CONNECT_SYNC=3,EXPORT=4,IMPORT=5;
    static final long MAX_FILE=20L*1024*1024,MAX_BUNDLE=100L*1024*1024;
    final Runnable syncLater=()->io.execute(()->syncFile());
    File store(){return new File(getFilesDir(),"data.json");}
    File attachments(){File f=new File(getFilesDir(),"attachments");f.mkdirs();return f;}
    @Override public void onCreate(Bundle state){super.onCreate(state);
        getWindow().setStatusBarColor(0xfff2f2f7);getWindow().setNavigationBarColor(0xfff2f2f7);
        if((getResources().getConfiguration().uiMode&48)==32){getWindow().setStatusBarColor(0xff000000);getWindow().setNavigationBarColor(0xff000000);}else getWindow().getDecorView().setSystemUiVisibility(android.view.View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR);
        web=new WebView(this);setContentView(web);web.setBackgroundColor(0xfff2f2f7);
        web.getSettings().setJavaScriptEnabled(true);web.getSettings().setDomStorageEnabled(true);
        web.getSettings().setAllowFileAccess(false);web.getSettings().setAllowContentAccess(false);
        web.addJavascriptInterface(new Bridge(),"Native");
        web.setWebViewClient(new WebViewClient(){
            @Override public boolean shouldOverrideUrlLoading(WebView v,WebResourceRequest r){if(!"quicknotes.local".equals(r.getUrl().getHost())){external(r.getUrl());return true;}return false;}
            @Override public WebResourceResponse shouldInterceptRequest(WebView v,WebResourceRequest r){Uri u=r.getUrl();if(!"https".equals(u.getScheme())||!"quicknotes.local".equals(u.getHost()))return response("text/plain",new ByteArrayInputStream(new byte[0]));try{String p=u.getPath();if(p.startsWith("/attachment/")){String id=p.substring(12);if(!safeId(id))throw new IOException("Invalid attachment");return response(mimeFor(id),new FileInputStream(new File(attachments(),id)));}String name=p.equals("/")?"index.html":p.substring(1);if(!Arrays.asList("index.html","app.js","model.js","style.css").contains(name))throw new IOException("Unknown asset");return response(name.endsWith(".js")?"application/javascript":name.endsWith(".css")?"text/css":"text/html",getAssets().open(name));}catch(Exception e){return response("text/plain",new ByteArrayInputStream(new byte[0]));}}
        });web.loadUrl("https://quicknotes.local/");
        if(Build.VERSION.SDK_INT>=33&&checkSelfPermission("android.permission.POST_NOTIFICATIONS")!=android.content.pm.PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{"android.permission.POST_NOTIFICATIONS"},8);
        io.execute(()->{try{Reminders.schedule(this,read());}catch(Exception e){error(e);}});
    }
    WebResourceResponse response(String mime,InputStream s){return new WebResourceResponse(mime,"UTF-8",s);}
    void external(Uri uri){try{if("https".equals(uri.getScheme())||"http".equals(uri.getScheme()))startActivity(new Intent(Intent.ACTION_VIEW,uri));}catch(Exception e){error(e);}}
    void js(String fn,Object arg){String value=arg instanceof JSONObject||arg instanceof JSONArray?arg.toString():JSONObject.quote(String.valueOf(arg));handler.post(()->{if(!destroyed)web.evaluateJavascript("window."+fn+"("+value+")",null);});}
    void error(Exception e){js("onNativeError",e.getMessage()==null?e.toString():e.getMessage());}
    @Override protected void onResume(){super.onResume();handler.removeCallbacks(syncLater);handler.postDelayed(syncLater,1200);}
    @Override public void onBackPressed(){web.evaluateJavascript("window.back()",result->{if(!"true".equals(result))super.onBackPressed();});}
    @Override protected void onDestroy(){destroyed=true;handler.removeCallbacks(syncLater);io.shutdown();web.destroy();super.onDestroy();}
    static boolean safeId(String id){return id!=null&&id.matches("[a-zA-Z0-9_-]{1,100}");}
    JSONObject read() throws Exception {if(!store().exists())return new JSONObject("{\"version\":1,\"lists\":[{\"id\":\"default\",\"title\":\"Reminders\",\"color\":\"#007aff\",\"icon\":\"list\",\"updated\":1}],\"items\":[]}");try(InputStream s=new FileInputStream(store())){return validate(new JSONObject(new String(bytes(s,MAX_BUNDLE),"UTF-8")));}}
    static JSONObject validate(JSONObject j)throws Exception {if(j.getInt("version")!=1)throw new IOException("Unsupported QuickNotes file");for(String key:new String[]{"lists","items"}){JSONArray a=j.getJSONArray(key);if(a.length()>100000)throw new IOException("Too many reminders");for(int n=0;n<a.length();n++){JSONObject x=a.getJSONObject(n);if(!safeId(x.getString("id"))||!x.has("updated"))throw new IOException("Invalid reminder record");x.getLong("updated");if(key.equals("lists")&&x.has("color")&&!x.getString("color").matches("#[0-9a-fA-F]{6}"))throw new IOException("Invalid list color");if(key.equals("items")){int priority=x.optInt("priority",0);if((x.has("priority")&&(!(x.opt("priority") instanceof Number)||x.optDouble("priority")!=priority))||priority<0||priority>3)throw new IOException("Invalid reminder priority");if((x.has("due")&&!(x.opt("due") instanceof Number))||x.optLong("due",0)<0)throw new IOException("Invalid due date");}}}return j;}
    static JSONObject merge(JSONObject a,JSONObject b)throws Exception {validate(a);validate(b);JSONObject out=new JSONObject().put("version",1);for(String key:new String[]{"lists","items"}){Map<String,JSONObject> map=new LinkedHashMap<>();for(JSONObject source:new JSONObject[]{a,b}){JSONArray arr=source.getJSONArray(key);for(int n=0;n<arr.length();n++){JSONObject x=arr.getJSONObject(n),old=map.get(x.getString("id"));if(old==null||x.getLong("updated")>old.getLong("updated")||(x.getLong("updated")==old.getLong("updated")&&x.toString().compareTo(old.toString())>0))map.put(x.getString("id"),x);}}out.put(key,new JSONArray(map.values()));}return out;}
    void write(JSONObject j)throws Exception {File temp=new File(getFilesDir(),"data.tmp");try(FileOutputStream out=new FileOutputStream(temp)){out.write(j.toString().getBytes("UTF-8"));out.getFD().sync();}if(!temp.renameTo(store()))throw new IOException("Could not save reminders");Reminders.schedule(this,j);}
    static byte[] bytes(InputStream s,long cap)throws IOException {ByteArrayOutputStream o=new ByteArrayOutputStream();byte[] buf=new byte[16384];int n;long total=0;while((n=s.read(buf))!=-1){total+=n;if(total>cap)throw new IOException("File exceeds size limit");o.write(buf,0,n);}return o.toByteArray();}
    String mimeFor(String id){try{JSONArray items=read().getJSONArray("items");for(int n=0;n<items.length();n++){JSONArray aa=items.getJSONObject(n).optJSONArray("attachments");if(aa!=null)for(int k=0;k<aa.length();k++)if(id.equals(aa.getJSONObject(k).optString("id")))return aa.getJSONObject(k).optString("mime","application/octet-stream");}}catch(Exception e){}return "application/octet-stream";}
    class Bridge {
        @JavascriptInterface public String load(){try{return read().toString();}catch(Exception e){error(e);return "{}";}}
        @JavascriptInterface public void save(String s){persist(s,true);}
        @JavascriptInterface public void saveMerged(String s){persist(s,false);}
        @JavascriptInterface public void attach(){handler.post(()->picker(Intent.ACTION_OPEN_DOCUMENT,"*/*",ATTACH,true));}
        @JavascriptInterface public void openAttachment(String id){if(!safeId(id))return;handler.post(()->{try{File f=new File(attachments(),id);if(!f.exists())throw new IOException("Attachment unavailable. Sync again to download it.");Uri uri=Uri.parse("content://"+getPackageName()+".attachments/"+id);startActivity(new Intent(Intent.ACTION_VIEW).setDataAndType(uri,mimeFor(id)).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION));}catch(Exception e){error(e);}});}
        @JavascriptInterface public void openUrl(String u){handler.post(()->external(Uri.parse(u)));}
        @JavascriptInterface public void createSync(){handler.post(()->picker(Intent.ACTION_CREATE_DOCUMENT,"application/zip",CREATE_SYNC,false));}
        @JavascriptInterface public void connectSync(){handler.post(()->picker(Intent.ACTION_OPEN_DOCUMENT,"*/*",CONNECT_SYNC,false));}
        @JavascriptInterface public void sync(){io.execute(()->syncFile());}
        @JavascriptInterface public void disconnectSync(){handler.post(()->{String u=getPreferences(0).getString("sync","");getPreferences(0).edit().remove("sync").apply();handler.removeCallbacks(syncLater);try{if(!u.isEmpty())getContentResolver().releasePersistableUriPermission(Uri.parse(u),Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION);}catch(Exception ignored){}js("onSyncStatus","Disconnected. Local reminders are kept.");});}
        @JavascriptInterface public void exportBackup(){handler.post(()->picker(Intent.ACTION_CREATE_DOCUMENT,"application/zip",EXPORT,false));}
        @JavascriptInterface public void importBackup(){handler.post(()->picker(Intent.ACTION_OPEN_DOCUMENT,"*/*",IMPORT,false));}
        @JavascriptInterface public void notificationSettings(){handler.post(()->{Intent i=new Intent("android.settings.APP_NOTIFICATION_SETTINGS").putExtra("android.provider.extra.APP_PACKAGE",getPackageName());startActivity(i);});}
    }
    void persist(String s,boolean sync){io.execute(()->{try{write(merge(read(),validate(new JSONObject(s))));if(sync)handler.post(()->{handler.removeCallbacks(syncLater);handler.postDelayed(syncLater,1800);});}catch(Exception e){error(e);}});}
    void picker(String action,String mime,int code,boolean multi){try{Intent i=new Intent(action).setType(mime).addCategory(Intent.CATEGORY_OPENABLE).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION);if(multi)i.putExtra(Intent.EXTRA_ALLOW_MULTIPLE,true);if(Intent.ACTION_CREATE_DOCUMENT.equals(action))i.putExtra(Intent.EXTRA_TITLE,code==EXPORT?"QuickNotes-backup.zip":"QuickNotes-sync.zip");startActivityForResult(i,code);}catch(Exception e){error(e);}}
    @Override protected void onActivityResult(int code,int result,Intent intent){super.onActivityResult(code,result,intent);if(result!=RESULT_OK||intent==null)return;if(code==ATTACH){ArrayList<Uri> uris=new ArrayList<>();if(intent.getClipData()!=null)for(int n=0;n<intent.getClipData().getItemCount();n++)uris.add(intent.getClipData().getItemAt(n).getUri());else if(intent.getData()!=null)uris.add(intent.getData());io.execute(()->addFiles(uris));return;}Uri uri=intent.getData();if(uri==null)return;
        if(code==CREATE_SYNC||code==CONNECT_SYNC){try{int flags=intent.getFlags()&(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION);if((flags&Intent.FLAG_GRANT_WRITE_URI_PERMISSION)==0)throw new IOException("This provider did not grant write access. Select a writable file.");getContentResolver().takePersistableUriPermission(uri,flags);}catch(Exception e){error(e);return;}}
        io.execute(()->{try{if(code==CREATE_SYNC||code==EXPORT){writeBundle(uri,read());if(code==CREATE_SYNC)getPreferences(0).edit().putString("sync",uri.toString()).apply();js("onSyncStatus",code==EXPORT?"Backup exported with attachments":"Sync file created and connected");}else if(code==IMPORT){JSONObject merged=merge(read(),readBundle(uri));write(merged);js("onDataMerged",merged);js("onSyncStatus","Backup merged successfully");}else if(code==CONNECT_SYNC){JSONObject merged=merge(read(),readBundle(uri));write(merged);writeBundle(uri,merged);getPreferences(0).edit().putString("sync",uri.toString()).apply();js("onDataMerged",merged);js("onSyncStatus","Connected and synced");}}catch(Exception e){error(e);}});
    }
    void addFiles(List<Uri> uris){JSONArray added=new JSONArray();for(Uri u:uris){File f=null;try{String name="Attachment",mime=getContentResolver().getType(u);try(Cursor c=getContentResolver().query(u,new String[]{OpenableColumns.DISPLAY_NAME},null,null,null)){if(c!=null&&c.moveToFirst())name=c.getString(0);}String id=UUID.randomUUID().toString();f=new File(attachments(),id);long size=0;try(InputStream in=getContentResolver().openInputStream(u);FileOutputStream out=new FileOutputStream(f)){if(in==null)throw new IOException("Cannot open attachment");byte[] buf=new byte[16384];int n;while((n=in.read(buf))!=-1){size+=n;if(size>MAX_FILE)throw new IOException("Each attachment must be 20 MB or smaller");out.write(buf,0,n);}}added.put(new JSONObject().put("id",id).put("name",name).put("mime",mime==null?"application/octet-stream":mime).put("size",size));}catch(Exception e){if(f!=null)f.delete();error(e);}}js("attachmentsAdded",added);}
    void syncFile(){String u=getPreferences(0).getString("sync","");if(u.isEmpty())return;js("onSyncStatus","Syncing…");try{Uri uri=Uri.parse(u);JSONObject merged=merge(read(),readBundle(uri));write(merged);writeBundle(uri,merged);js("onDataMerged",merged);js("onSyncStatus","Synced · "+java.text.DateFormat.getTimeInstance(java.text.DateFormat.SHORT).format(new Date()));}catch(Exception e){js("onSyncStatus","Sync failed. Local data kept. "+e.getMessage());}}
    JSONObject readBundle(Uri uri)throws Exception {File stage=new File(getCacheDir(),"incoming");stage.mkdirs();ArrayList<File> staged=new ArrayList<>();JSONObject manifest=null;long total=0;try(InputStream raw=getContentResolver().openInputStream(uri);ZipInputStream zip=new ZipInputStream(raw)){ZipEntry e;while((e=zip.getNextEntry())!=null){String name=e.getName();if(name.equals("data.json")){byte[] content=bytes(zip,5*1024*1024);total+=content.length;manifest=validate(new JSONObject(new String(content,"UTF-8")));}else if(name.startsWith("attachments/")){String id=name.substring(12);if(!safeId(id))throw new IOException("Unsafe attachment in backup");File f=new File(stage,id);staged.add(f);try(FileOutputStream out=new FileOutputStream(f)){byte[] b=new byte[16384];int n;long file=0;while((n=zip.read(b))!=-1){file+=n;total+=n;if(file>MAX_FILE||total>MAX_BUNDLE)throw new IOException("Backup exceeds 100 MB limit");out.write(b,0,n);}}}else throw new IOException("Unrecognized file in backup");zip.closeEntry();if(total>MAX_BUNDLE)throw new IOException("Backup exceeds size limit");}if(manifest==null)throw new IOException("No reminder data in this file");for(File f:staged){File dest=new File(attachments(),f.getName());if(dest.exists())f.delete();else if(!f.renameTo(dest))throw new IOException("Cannot restore attachment");}for(JSONObject a:referenced(manifest)){if(!new File(attachments(),a.getString("id")).exists())throw new IOException("Backup is missing attachment "+a.optString("name"));}return manifest;}finally{for(File f:staged)f.delete();}}
    List<JSONObject> referenced(JSONObject j)throws Exception {Map<String,JSONObject> out=new LinkedHashMap<>();JSONArray items=j.getJSONArray("items");for(int n=0;n<items.length();n++){JSONObject i=items.getJSONObject(n);if(i.optBoolean("deleted"))continue;JSONArray a=i.optJSONArray("attachments");if(a==null)continue;for(int k=0;k<a.length();k++){JSONObject f=a.getJSONObject(k);if(!safeId(f.getString("id")))throw new IOException("Invalid attachment ID");out.put(f.getString("id"),f);}}return new ArrayList<>(out.values());}
    void writeBundle(Uri uri,JSONObject data)throws Exception {File pending=new File(getCacheDir(),"pending.zip");long total=data.toString().getBytes("UTF-8").length;try(ZipOutputStream zip=new ZipOutputStream(new FileOutputStream(pending))){zip.putNextEntry(new ZipEntry("data.json"));zip.write(data.toString().getBytes("UTF-8"));zip.closeEntry();for(JSONObject a:referenced(data)){File f=new File(attachments(),a.getString("id"));if(!f.exists())throw new IOException("Missing attachment: "+a.optString("name"));total+=f.length();if(total>MAX_BUNDLE)throw new IOException("Sync supports up to 100 MB. Remove large attachments.");zip.putNextEntry(new ZipEntry("attachments/"+f.getName()));try(InputStream in=new FileInputStream(f)){byte[] buf=new byte[16384];int n;while((n=in.read(buf))!=-1)zip.write(buf,0,n);}zip.closeEntry();}}
        // Keep a previous local bundle before truncating the remote provider document.
        File recovery=new File(getFilesDir(),"last-sync.zip");try(InputStream in=new FileInputStream(pending);OutputStream out=new FileOutputStream(recovery)){byte[] b=new byte[16384];int n;while((n=in.read(b))!=-1)out.write(b,0,n);}
        try(OutputStream out=getContentResolver().openOutputStream(uri,"wt");InputStream in=new FileInputStream(pending)){if(out==null)throw new IOException("Provider cannot write this file");byte[] b=new byte[16384];int n;while((n=in.read(b))!=-1)out.write(b,0,n);}pending.delete();
    }
}
